"""Exercises 1100–1103: reconstruct signs, both roots and tangent from an actual point on the upper arc."""
import argparse,json
from math import acos,asin,degrees,sqrt
from itertools import product
from upper_semicircle import ROOT,BOOK,arc,author

OUT=ROOT/'geometry-course/textbook/data/trigonometric-signs.json'
FORMS={'√3/2':['√3/2','sqrt(3)/2'],'√5/3':['√5/3','sqrt(5)/3'],'-√3/3':['-√3/3','-1/√3','-sqrt(3)/3','-1/sqrt(3)'],'√15/4':['√15/4','sqrt(15)/4'],'0':['0','0,0','0.0'],'1':['1','+1'],'-3/4':['-3/4','-0,75','-0.75','-¾']}


def single(label,degrees_value):
    return arc(label,[('M',degrees_value)],edges=[('O','M')],projections=[('M','H')])


def twin(label,y):
    alpha=degrees(asin(y));return arc(label,[('M',alpha),('N',180-alpha)],edges=[('O','M'),('O','N')],lines=[((-1.05,y),(1.05,y))])


def grade(c,formats,feedback,prompt='Введи точное значение. Для корня можно записать √число или sqrt(число).'):
    c['answer']=dict(mode='exact',accepted=list(dict.fromkeys(formats)),feedback=feedback,prompt=prompt);return c


def sine():
    rows=[]
    for part,x,given,answer,work,test,newx,newgiven,transfer,sourceprobe,newprobe in [
        ('а',.5,'1/2','√3/2','sin²α=1−1/4=3/4','У положительного косинуса |x|<1 точка правее O и выше Ox.',.6,'3/5','sin²β=1−9/25=16/25, sin β=4/5',('Числитель дроби sin²α=…/4?','3'),('У новой дроби sin β=…/5 какой числитель?','4')),
        ('б',-2/3,'−2/3','√5/3','sin²α=1−4/9=5/9','Отрицательный косинус переносит точку влево; ордината верхней дуги остаётся положительной.',-.8,'−4/5','sin²β=1−16/25=9/25, sin β=3/5',('Числитель дроби sin²α=…/9?','5'),('У новой дроби sin β=…/5 какой числитель?','3')),
        ('в',-1,'−1','0','sin²α=1−1=0','При x=−1 единственная точка верхней дуги B=(−1;0).',1,'1','sin²β=0, значит sin β=0; это уже правый конец диаметра',('Чему равен квадрат синуса в исходной точке?','0'),('Какова абсцисса новой точки при положительном предельном косинусе?','1'))]:
        alpha=degrees(acos(x));beta=degrees(acos(newx));views=[single('Точка по заданной абсциссе',alpha),arc('Ордината выбранной точки',[('M',alpha)],edges=[('O','M')],projections=[('M','H')],lines=[((x,-.08),(x,1.06))]),single('Другая абсцисса',beta)]
        hint='В равенстве sin²α=1−cos²α сначала возведи косинус в квадрат. На верхней дуге синус неотрицателен.'
        reason=f'{work}. Так как 0°≤α≤180°, получаем sin α={answer}. {test}'
        c=author(1100,part,[275],f'Известно cos α={given}, угол α от 0° до 180°. Найди sin α и обоснуй знак.',reason,hint,[('Найди квадрат ординаты',work+'. Это число равно квадрату ординаты точки на единичной полуокружности.','Квадрат отрицательного и положительного значений одного модуля одинаков.'),('Выбери допустимый корень',reason,'У верхней дуги выбирают неотрицательный синус.'),('Измени косинус',f'Если cos β={newgiven}, то {transfer}.','При новой абсциссе пересчитай квадрат и проверь положение точки.')],views,[(sourceprobe[0],sourceprobe[1],work+'.'),(newprobe[0],newprobe[1],'Сначала проверь равенство квадратов для новой точки.')],[100,101])
        rows.append(grade(c,FORMS[answer],hint))
    return rows


def cosine():
    rows=[]
    for part,y,given,absx,work,newy,repeat,q1,v1,q2,v2 in [
        ('а',sqrt(3)/2,'√3/2','1/2','cos²α=1−3/4=1/4',.8,'При sin β=4/5 имеем cos²β=9/25; подходят −3/5 и 3/5.','Сколько абсцисс у исходной ординаты?','2','Числитель положительного нового косинуса, записанного со знаменателем 5?','3'),
        ('б',.25,'1/4','√15/4','cos²α=1−1/16=15/16',.6,'При sin β=3/5 имеем cos²β=16/25; подходят −4/5 и 4/5.','Чему равен числитель исходного квадрата косинуса со знаменателем 16?','15','Числитель положительного нового косинуса со знаменателем 5?','4'),
        ('в',0,'0','1','cos²α=1',1,'При sin β=1 линия касается дуги в C=(0;1); тогда единственное значение cos β=0.','Сколько точек верхней дуги имеют y=0?','2','Каково единственное значение нового косинуса при sin β=1?','0')]:
        alpha=degrees(asin(y));beta=degrees(asin(newy));views=[single('Точка с неотрицательной абсциссой',alpha),twin('Все точки с заданной ординатой',y),twin('Другой уровень синуса',newy)]
        hint='Для одной ординаты верхней дуги могут существовать две абсциссы. При числе y<1 рассмотрим обе стороны от Oy.'
        reason=f'{work}. Поэтому значения косинуса равны −{absx} и {absx}. Оба реализуются на верхней дуге в точках, симметричных относительно Oy.'
        c=author(1101,part,[275],f'Дано sin α={given}, причём 0°≤α≤180°. Найди все возможные значения cos α.',reason,hint,[('Найди модуль косинуса',work+f'. Модуль абсциссы равен {absx}.','Из одного уравнения для квадрата знак абсциссы не следует.'),('Проверь обе стороны верхней дуги',reason,'Точки при углах α и 180°−α обладают одной ординатой.'),('Сравни новый горизонтальный уровень',repeat,'Если новый уровень касается дуги в одной точке, проверяй этот граничный случай отдельно.')],views,[(q1,v1,'Сопоставь горизонтальную прямую с дугой и проверь вычисленный квадрат.'),(q2,v2,'Работай с новой ординатой и уравнением x²+y²=1.')],[100,101])
        roots=FORMS.get(absx,[absx]);allowed=[]
        if absx=='1/2':roots=roots+['½','0,5','0.5']
        for root in roots:
            if root.startswith('+'):continue
            allowed+=['±'+root,'+/-'+root]
            for sep in (';','; ',' и '):allowed.extend(['-'+root+sep+root,root+sep+'-'+root])
        rows.append(grade(c,allowed,hint,'Введи оба значения через точку с запятой или в виде ±число.'))
    return rows


def tangent():
    rows=[]
    for part,task,angle,reason,first,second,altangle,alt,q1,v1,q2,v2,answer in [
       ('а','cos α=1',0,'Единственная точка A=(1;0), поэтому tg α=0/1=0.','Из максимального косинуса следует α=0°.','Ордината равна 0, а знаменатель cos α равен 1.',90,'При cos β=0 имеем β=90° и tg β не определён. В знаменателе ноль.','Какова ордината A?','0','Каков знаменатель sin β/cos β на новом рисунке?','0','0'),
       ('б','cos α=−√3/2',150,'Синус верхней дуги 1/2. Тогда tg α=(1/2)/(−√3/2)=−1/√3=−√3/3.','Вычисли sin²α=1−3/4=1/4 и выбери положительный корень.','Косинус отрицателен, поэтому положительное 1/2 делится на отрицательное число.',degrees(acos(-.6)),'Для cos β=−3/5 имеем sin β=4/5, tg β=−4/3.','Числитель найденного синуса со знаменателем 2?','1','Числитель нового тангенса в несократимой дроби со знаменателем 3?','-4','-√3/3'),
       ('в','sin α=√2/2 и 0°<α<90°',45,'Косинус острого угла положителен. cos²α=1/2 и cos α=√2/2. Числитель и знаменатель равны, tg α=1.','Из тождества найди cos²α=1−1/2.','Острый угол помещает M справа от Oy. Поэтому cos α положителен.',135,'Если тот же синус относится к тупому углу 135°, косинус −√2/2 и тангенс −1.','Какой знак у исходного косинуса? Введи 1 или −1.','1','Каков новый тангенс при тупом угле?','-1','1'),
       ('г','sin α=3/5 и 90°<α<180°',degrees(acos(-.8)),'По тождеству cos²α=16/25. У тупого угла cos α=−4/5. Поэтому tg α=(3/5)/(−4/5)=−3/4.','Синус положителен, а положение слева от Oy определяет знак косинуса.','Деля 3/5 на −4/5, сократи общий знаменатель 5.',degrees(acos(.8)),'Для острого угла с тем же синусом берём положительный косинус 4/5, поэтому tg β=3/4.','Числитель исходного косинуса со знаменателем 5?','-4','Числитель нового тангенса со знаменателем 4?','3','-3/4')]:
        hint='Тангенс равен sin α / cos α. Сначала определи допустимый знак недостающей координаты, затем проверь знаменатель.'
        views=[single('Точка исходного угла',angle),arc('Проекции для отношения y/x',[('M',angle)],edges=[('O','M')],projections=[('M','H')]),single('Новые данные и другое отношение',altangle)]
        c=author(1102,part,[275],f'Найди tg α, если {task}. Используй верхнюю единичную полуокружность.',reason,hint,[('Восстанови недостающую координату',first,'Квадрат координаты вычисляется по x²+y²=1.'),('Вычисли отношение',second+' '+reason,'Сохрани знак знаменателя.'),('Измени условие',alt,'Переключи рисунок перед проверкой нового случая.')],views,[(q1,v1,'Сначала определи координату на нужной стороне от Oy.'),(q2,v2,'Используй новое положение точки на дуге.')],[100,101])
        rows.append(grade(c,FORMS[answer],hint))
    return rows


def special_angles():
    a,b,c=[single('Угол '+str(n)+'°',n) for n in [120,135,150]];repeat=single('Сравнение с углом 30°',30)
    why='Для 120° тройка (sin;cos;tg) равна (√3/2;−1/2;−√3), для 135° — (√2/2;−√2/2;−1), для 150° — (1/2;−√3/2;−√3/3). Синус дополнительного до 180° угла сохраняется, косинус меняет знак, поэтому тангенс также меняет знак.'
    hint='Сопоставь трём тупым углам острые 60°, 45°, 30°. В полученной тройке сначала синус, затем косинус, затем их отношение.'
    lesson=author(1103,None,[275],'Найди синус, косинус и тангенс углов 120°, 135°, 150°. Укажи все девять значений, сопоставив каждому углу его проекции.',why,hint,[('Отрази луч 60°','До 180° от 120° не хватает 60°. Поэтому y=√3/2, x=−1/2 и y/x=−√3. Сумма квадратов координат равна 1.','При отражении относительно Oy меняется горизонтальная часть.'),('Проверь 135°','К 135° соответствует 45°. Модули координат равны √2/2, но x отрицателен. Получаем sin=√2/2, cos=−√2/2, tg=−1.','Тангенс численно −1, хотя синус положителен.'),('Получай последнюю тройку и сравни с новым острым углом','У 150° значения (1/2;−√3/2;−√3/3). У острого 30° тот же синус, положительные cos=√3/2 и tg=√3/3.','Каждую из трёх строк проверь отдельно подстановкой в тождество и делением.')],[a,b,c,repeat],[('Каков тангенс 135°?','-1','Равные по модулю координаты здесь имеют разные знаки.'),('Какой знак тангенса 30°? Введи 1 или −1.','1','Здесь обе координаты положительны.')],[100,101])
    canonical=['√3/2','-1/2','-√3','√2/2','-√2/2','-1','1/2','-√3/2','-√3/3']
    forms=[]
    for root,sep,final in product(('√','sqrt'),(';','; '),('-√3/3','-1/√3')):
        row=canonical[:-1]+[final]
        if root=='sqrt':row=[t.replace('√2','sqrt(2)').replace('√3','sqrt(3)') for t in row]
        forms.append(sep.join(row))
    return grade(lesson,forms,hint,'Через точку с запятой введи девять значений: sin, cos, tg для 120°, затем для 135° и для 150°. Используй √ или sqrt().')


def build():return {'bookId':BOOK,'lessons':sine()+cosine()+tangent()+[special_angles()]}


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args();data=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if args.check:assert OUT.read_text()==data
    else:OUT.write_text(data)
